xml.Script:
        Colors[0] := 'FFFFFF'; // White
        Colors[1] := 'FFFF00'; // Yellow
        Colors[2] := '0033EE'; // Blue
        Colors[3] := 'FF7700'; // Orange
        Colors[4] := '00AA00'; // Green
        Colors[5] := 'DD0011'; // Red
        Colors[6] := 'EE22BB'; // Pink
        Colors[7] := '9900DD'; // Violett
        Colors[8] := '808080'; // Gray

        R := 0.9;
        H := R * 0.5;
        L := R * cos(Pi/8);
        D := R * sin(Pi/8);
        R1 := R * 0.75;
        WD := L - R1;

        N := 10;
        M := 2 * N + 9;
        for i := 0 to N do begin
            x[i] := L - R1 * cos(Pi/4 / N * i);
            y[i] :=-D + R1 * sin(Pi/4 / N * i);
        end;
        x[N + 1] := x[N] + WD * sqrt(2) * 2;
        y[N + 1] := y[N] + WD * sqrt(2) * 2;
        x[N + 2] := x[N + 1] - WD * sqrt(2);
        y[N + 2] := y[N + 1] + WD * sqrt(2);
        x[N + 3] := 0;
        y[N + 3] := y[N + 2] - x[N + 2];

        for i := 0 to N + 2 do begin
            x[N + 4 + i] :=-x[N + 2 - i];
            y[N + 4 + i] := y[N + 2 - i];
        end;

        x[2 * N + 7] :=-WD;
        y[2 * N + 7] :=-D - 3 * WD;
        x[2 * N + 8] := WD;
        y[2 * N + 8] :=-D - 3 * WD;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i;
i2 := (i + 1) mod M;
Inc(i);
